const fs=require('fs'); const {spawn}=require('child_process'); const ROOT='/Users/dq/Documents/ERP/hub-erp-v0'; const FRONT='http://127.0.0.1:8099'; const pages=['purchase-return-request.html','purchase-return-request-create.html','purchase-return.html','purchase-return-create.html']; const ev={runTag:`P1FEBROWSER-${Date.now()}`,startedAt:new Date().toISOString(),checks:[],defects:[]}; function sleep(ms){return new Promise(r=>setTimeout(r,ms))} class CDP{constructor(ws){this.wsUrl=ws;this.id=0;this.pending=new Map()} async connect(){this.ws=new WebSocket(this.wsUrl); await new Promise((res,rej)=>{this.ws.onopen=res;this.ws.onerror=rej}); this.ws.onmessage=ev=>{const m=JSON.parse(ev.data); if(m.id&&this.pending.has(m.id)){const p=this.pending.get(m.id);this.pending.delete(m.id);m.error?p.reject(new Error(m.error.message)):p.resolve(m.result)}}} send(method,params={}){const id=++this.id;this.ws.send(JSON.stringify({id,method,params}));return new Promise((resolve,reject)=>{this.pending.set(id,{resolve,reject});setTimeout(()=>reject(new Error('timeout '+method)),10000)})} async eval(expression){const r=await this.send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});return r.result.value} }
function add(id,name,ok,detail){const item={id,name,status:ok?'PASS':'FAIL',detail,at:new Date().toISOString()}; ev.checks.push(item); if(!ok)ev.defects.push(item); console.log(`${ok?'✅':'❌'} ${id} ${name}`)}
(async()=>{const port=9400+Math.floor(Math.random()*200); const proc=spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',['--headless=new','--disable-gpu',`--remote-debugging-port=${port}`,`--user-data-dir=/tmp/${ev.runTag}-chrome`,'about:blank'],{stdio:'ignore'}); for(let i=0;i<50;i++){try{if((await fetch(`http://127.0.0.1:${port}/json/version`)).ok)break}catch{} await sleep(100)} const target=await (await fetch(`http://127.0.0.1:${port}/json/new?about:blank`,{method:'PUT'})).json(); const c=new CDP(target.webSocketDebuggerUrl); await c.connect(); await c.send('Page.enable'); await c.send('Runtime.enable'); await c.send('Page.addScriptToEvaluateOnNewDocument',{source:`window.__p1Fetch=[];const oldFetch=window.fetch;window.fetch=function(){window.__p1Fetch.push(String(arguments[0]));return oldFetch.apply(this,arguments)}`}); for(const p of pages){await c.send('Page.navigate',{url:`${FRONT}/pages/${p}`}); await sleep(1200); const info=await c.eval(`(()=>({url:location.href,title:document.title,text:document.body.innerText.slice(0,500),fetches:window.__p1Fetch||[],hasApi:document.documentElement.innerHTML.includes('purchase-return-requests')||document.documentElement.innerHTML.includes('purchase-returns/'),hasLocal:document.documentElement.innerHTML.includes('localStorage.getItem')||document.documentElement.innerHTML.includes('localStorage.setItem')}))()`); const ok=info.fetches.some(x=>/purchase-return/.test(x))||info.hasApi&&!info.hasLocal; add(`P1-BROWSER-${p}`,'P1 页面真实 API 浏览器验收',ok,info)} proc.kill('SIGTERM'); ev.summary={total:ev.checks.length,pass:ev.checks.filter(x=>x.status==='PASS').length,fail:ev.checks.filter(x=>x.status==='FAIL').length}; ev.finishedAt=new Date().toISOString(); fs.writeFileSync(`${ROOT}/采购模块P1采购退换货浏览器验收证据-20260720.json`,JSON.stringify(ev,null,2)); console.log('EVIDENCE='+`${ROOT}/采购模块P1采购退换货浏览器验收证据-20260720.json`); console.log(JSON.stringify(ev.summary)); if(ev.summary.fail)process.exitCode=2})().catch(e=>{ev.fatal=String(e.stack||e);fs.writeFileSync(`${ROOT}/采购模块P1采购退换货浏览器验收证据-20260720.json`,JSON.stringify(ev,null,2));console.error(e);process.exit(1)});
